import React, {
  LabelHTMLAttributes,
  HTMLAttributes,
  PropsWithChildren,
  ReactNode,
  useId,
} from "react";
import clsx from "clsx";
import { FormControl as FormControlStyles } from "@airbus/styles";
import { createUseStyles } from "../../lib/styling";
import Link from "../Link";
import { CommonProps } from "../helperTypes";

type Props = PropsWithChildren<{
  /** Specify the label for screen readers */
  "aria-label"?: string;
  /** Error state flag */
  error?: boolean;
  /** Error message */
  errorText?: string;
  /** help link label */
  helpLinkLabel?: string;
  /** Help text below input */
  helpText?: string;
  /**
   * The id of the control.
   * Use this property to make `label` and `helpText` accessible for screen readers.
   */
  id?: string;
  /* Informative state flag */
  info?: boolean;
  /** The label of the control */
  label?: string;
  /** Adornment component to display near the label */
  labelAdornment?: ReactNode;
  /**
   * @param {MouseEvent<HTMLAnchorElement>} event React's original MouseEvent.
   */
  onHelpLinkClick?(event: React.MouseEvent<HTMLAnchorElement>): void;
  /** The placeholder to display */
  placeholder?: string;
  /** If `true`, the control is mandatory. */
  required?: boolean;
  /** Success state flag */
  success?: boolean;
  /** Success message */
  successText?: string;
}>;

export type FormControlProps = Props & CommonProps;

const useStyles = createUseStyles(FormControlStyles, "formcontrol");

const FormControl = (props: FormControlProps) => {
  const {
    "aria-label": ariaLabel,
    children,
    className,
    error,
    errorText,
    helpLinkLabel,
    helpText,
    id: idProp,
    info,
    label,
    labelAdornment,
    onHelpLinkClick,
    placeholder,
    required,
    success,
    successText,
    ...rest
  } = props;
  const defaultId = `formcontrol-${useId()}`;
  const id = idProp || defaultId;
  const classes = useStyles();

  if (!children) return null;
  const control = React.Children.only(children);
  if (!React.isValidElement(control)) {
    return null;
  }

  const controlProps = {
    id,
    required,
    placeholder: placeholder,
    "aria-labelledby": label ? `${id}-label` : undefined,
    "aria-label": ariaLabel,
    className: classes.control,
    info,
    valid: success,
    invalid: error,
  };
  const controlChild = React.cloneElement<any>(control, controlProps);
  const hasHelp = (error && errorText) || (success && successText) || helpText;

  return (
    <div
      className={clsx(
        className,
        classes.root,
        info && classes._info,
        error && classes._error,
        success && classes._success
      )}
      {...rest}
    >
      {label && (
        <FormControlLabel htmlFor={id} id={`${id}-label`}>
          {label}
          {labelAdornment && (
            <div className={classes.info}>{labelAdornment}</div>
          )}
          {!required && <div className={classes.optional}>(Optional)</div>}
        </FormControlLabel>
      )}

      <div className={classes.control}>{controlChild}</div>

      {hasHelp && (
        <FormControlHelptext>
          {error ? errorText : success ? successText : helpText}
          {helpLinkLabel && (
            <div className={classes.helplink}>
              <Link
                size="xsmall"
                tabIndex={0}
                onClick={onHelpLinkClick}
              >
                {helpLinkLabel}
              </Link>
            </div>
          )}
        </FormControlHelptext>
      )}
    </div>
  );
};
export default FormControl;

export const FormControlLabel = ({
  children,
  ...rest
}: PropsWithChildren<LabelHTMLAttributes<HTMLLabelElement>>) => {
  const classes = useStyles();
  return (
    <label className={clsx(classes.label)} {...rest}>
      {children}
    </label>
  );
};

export const FormControlHelptext = ({
  children,
  ...rest
}: PropsWithChildren<HTMLAttributes<HTMLDivElement>>) => {
  const classes = useStyles();
  return (
    <div className={clsx(classes.help)} {...rest}>
      {children}
    </div>
  );
};
